# Function to generate patient IDs
generate_patient_id &lt;- function(site_code, patient_number) {
  # Format: SITE001-P-0001
  formatted_number &lt;- str_pad(patient_number, 4, pad = "0")
  patient_id &lt;- paste0(site_code, "-P-", formatted_number)
  return(patient_id)
}

