for(i in seq_along(test_medications)) {
  result &lt;- extract_dosage_safe(test_medications[i])
  cat(sprintf("Input: '%s' -&gt; Output: '%s'\n", 
              ifelse(is.na(test_medications[i]), "NA", test_medications[i]), 
              result))
}

